package io.github.addxiaoyi.starchronicle.core;

import com.fasterxml.jackson.databind.ObjectMapper;
import io.github.addxiaoyi.starchronicle.config.*;
import io.github.addxiaoyi.starchronicle.config.StoryDefinition.*;
import io.github.addxiaoyi.starchronicle.persistence.SqliteStore;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class DefinitionCanonicalCodecTest {
    private static final String V1="{\"id\":\"golden\",\"version\":\"1\",\"title\":\"旧史 · star\",\"scope\":\"WORLD\",\"triggers\":[\"ROOT\",\"SECOND\"],\"condition\":null,\"start\":\"end\",\"cooldownSeconds\":60,\"nodes\":{\"end\":{\"text\":\"Done\",\"script\":null,\"quest\":null,\"quorum\":1,\"choices\":{},\"effects\":[],\"terminal\":true}}}";
    private static StoryDefinition golden(){return new StoryDefinition("golden","1","旧史 · star",Scope.WORLD,List.of("ROOT","SECOND"),null,"end",60,Map.of("end",new Node("Done",null,null,1,Map.of(),List.of(),true)));}
    private static StoryDefinition unit(StoryDefinition d,VoteUnit unit){return new StoryDefinition(d.id(),d.version(),d.title(),d.scope(),d.triggers(),d.condition(),d.start(),d.cooldownSeconds(),d.nodes(),unit);}

    @Test void frozenV1GoldenBytesAreExactlyTheReleasedShapeIncludingUtf8AndNullFields(){assertEquals(V1,DefinitionCanonicalCodec.encodeV1(golden()));assertEquals("33ed2b505673d7e2f607cb54d41b22e869d69a7af0d2e9a8266baeb0b905e36f",DefinitionCanonicalCodec.sha256(V1));assertEquals(V1,SqliteStore.json(golden()));assertEquals(golden(),DefinitionCanonicalCodec.verifyAndDecode(1,V1,DefinitionCanonicalCodec.sha256(V1)));}
    @Test void v2WritesItsExplicitFieldInAFixedPositionIndependentlyOfGenericSnapshotSerialization(){String v2=V1.substring(0,V1.length()-1)+",\"voteUnit\":\"PLAYER\"}";assertEquals(v2,DefinitionCanonicalCodec.encodeV2(golden()));assertFalse(SqliteStore.json(golden()).contains("voteUnit"));assertEquals(golden(),DefinitionCanonicalCodec.verifyAndDecode(2,v2,DefinitionCanonicalCodec.sha256(v2)));}
    @Test void rawHashIsCheckedBeforeParsingOrApplyingAnyDefaults(){var wrong=assertThrows(IllegalStateException.class,()->DefinitionCanonicalCodec.verifyAndDecode(1,"{broken","0".repeat(64)));assertTrue(wrong.getMessage().contains("raw payload fingerprint"));var malformed=assertThrows(IllegalStateException.class,()->DefinitionCanonicalCodec.verifyAndDecode(1,"{broken",DefinitionCanonicalCodec.sha256("{broken")));assertTrue(malformed.getMessage().contains("Invalid canonical definition V1"));}
    @Test void whitespaceIsPartOfRawEvidenceEvenWhenItDoesNotChangeParsedMeaning(){String pretty=" \n"+V1+"\n";assertThrows(IllegalStateException.class,()->DefinitionCanonicalCodec.verifyAndDecode(1,pretty,DefinitionCanonicalCodec.sha256(V1)));assertEquals(golden(),DefinitionCanonicalCodec.verifyAndDecode(1,pretty,DefinitionCanonicalCodec.sha256(pretty)));}
    @Test void newV2PayloadMustUseTheFrozenCanonicalWriterEvenWithASelfConsistentRawHash(){String canonical=DefinitionCanonicalCodec.encodeV2(golden()),pretty="\n"+canonical+"\n";assertThrows(IllegalStateException.class,()->DefinitionCanonicalCodec.verifyAndDecode(2,pretty,DefinitionCanonicalCodec.sha256(pretty)));assertEquals(golden(),DefinitionCanonicalCodec.decode(2,pretty));}
    @Test void frozenV1DoesNotAcceptANewDtoFieldEvenWhenItSaysPlayer(){String added=DefinitionCanonicalCodec.encodeV2(golden());assertThrows(IllegalStateException.class,()->DefinitionCanonicalCodec.decode(1,added));assertThrows(IllegalStateException.class,()->DefinitionCanonicalCodec.decode(2,V1));}
    @Test void nationVotingHasADifferentSemanticFingerprintAndCannotBeEncodedAsV1(){var national=unit(golden(),VoteUnit.NATION);assertNotEquals(DefinitionCanonicalCodec.fingerprintV2(golden()),DefinitionCanonicalCodec.fingerprintV2(national));assertThrows(IllegalArgumentException.class,()->DefinitionCanonicalCodec.encodeV1(national));assertEquals(national,DefinitionCanonicalCodec.decode(2,DefinitionCanonicalCodec.encodeV2(national)));}
    @Test void omittedExplicitPlayerAndOldConstructorHaveEqualSemantics()throws Exception{ObjectMapper mapper=new ObjectMapper();StoryDefinition absent=mapper.readValue(V1,StoryDefinition.class),explicit=mapper.readValue(V1.substring(0,V1.length()-1)+",\"voteUnit\":\"PLAYER\"}",StoryDefinition.class);assertEquals(golden(),absent);assertEquals(absent,explicit);assertEquals(DefinitionCanonicalCodec.fingerprintV2(absent),DefinitionCanonicalCodec.fingerprintV2(explicit));}
    @Test void unknownFieldsDuplicateFieldsTrailingDocumentsAndScalarCoercionsAreRejected(){for(String invalid:List.of(V1.replace("\"id\":\"golden\"","\"id\":\"golden\",\"id\":\"other\""),V1.replace("\"title\":","\"future\":true,\"title\":"),V1+" {}",V1.replace("\"cooldownSeconds\":60","\"cooldownSeconds\":\"60\""),V1.replace("\"terminal\":true","\"terminal\":\"true\"")))assertThrows(IllegalStateException.class,()->DefinitionCanonicalCodec.decode(1,invalid),invalid);}
    @Test void nestedConditionsChoicesAndEffectsUseTheFrozenFieldProtocol(){Condition condition=new Condition(List.of(new Condition(null,null,null,"player.role","eq","scholar"),new Condition(null,null,new Condition(null,null,null,"region.closed","exists",null),null,null,null)),null,null,null,null,null);var effects=List.of(new Effect("honor","honor","player","3",null),new Effect("history","history","REMEMBERED","quoted \"text\"",null));var nodes=new LinkedHashMap<String,Node>();nodes.put("vote",new Node("Choose","native-scene","native-quest",2,Map.of("yes",new Choice("Yes","end",condition,"choose.permission",effects)),List.of(),false));nodes.put("end",new Node("End",null,null,1,Map.of(),effects,true));var complex=new StoryDefinition("complex","1","Complex",Scope.WORLD,List.of("ROOT"),condition,"vote",0,nodes);String encoded=DefinitionCanonicalCodec.encodeV1(complex);assertEquals(SqliteStore.json(complex),encoded);assertEquals(complex,DefinitionCanonicalCodec.decode(1,encoded));assertEquals(complex,DefinitionCanonicalCodec.decode(2,DefinitionCanonicalCodec.encodeV2(complex)));assertTrue(encoded.indexOf("\"end\":")<encoded.indexOf("\"vote\":"));}
    @Test void nativeBindingsAndOrderedListsAreNotStrippedOrSortedAway(){var d=golden();var reordered=new StoryDefinition(d.id(),d.version(),d.title(),d.scope(),List.of("SECOND","ROOT"),null,d.start(),d.cooldownSeconds(),d.nodes());var bound=new StoryDefinition(d.id(),d.version(),d.title(),d.scope(),d.triggers(),null,d.start(),d.cooldownSeconds(),Map.of("end",new Node("Done","registered-scene",null,1,Map.of(),List.of(),true)));assertNotEquals(DefinitionCanonicalCodec.fingerprintV2(d),DefinitionCanonicalCodec.fingerprintV2(reordered));assertNotEquals(DefinitionCanonicalCodec.fingerprintV2(d),DefinitionCanonicalCodec.fingerprintV2(bound));}
    @Test void unsupportedProtocolsAndMalformedHashesFailClosed(){assertThrows(IllegalArgumentException.class,()->DefinitionCanonicalCodec.decode(3,V1));assertThrows(IllegalArgumentException.class,()->DefinitionCanonicalCodec.encode(golden(),0));for(String hash:List.of("","x".repeat(64),"A".repeat(64),"0".repeat(63)))assertThrows(IllegalStateException.class,()->DefinitionCanonicalCodec.verifyAndDecode(1,V1,hash));}
}
